import { defineConfig } from "orval"

/**
 * openapi.json is generated by the Go API and committed. orval runs offline against that
 * file in CI — it never boots the Go server.
 *
 * Regenerate after changing any Huma operation:
 *   make openapi   # openapi.json from the Go routes
 *   make orval     # typed client from openapi.json
 */
export default defineConfig({
  fold: {
    input: "./openapi.json",
    output: {
      mode: "tags-split",
      target: "lib/api/generated/endpoints",
      schemas: "lib/api/generated/model",
      client: "react-query",
      override: {
        mutator: {
          path: "./lib/api/mutator.ts",
          name: "customInstance",
        },
      },
    },
  },
})